// Package requestlog records a fixed, credential-free HTTP request summary.
// Authentication and MCP parsing enrich it only after validating the request.
package requestlog

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"log/slog"
	"net/http"
	"strings"
	"sync"
	"time"
)

const Header = "X-Request-ID"

type contextKey struct{}

type requestInfo struct {
	mu                              sync.Mutex
	id, identity, tenant, agent, op string
}

// ID is generated by the gateway, never taken from caller-controlled headers.
func ID(ctx context.Context) string {
	if info, ok := ctx.Value(contextKey{}).(*requestInfo); ok {
		return info.id
	}
	return ""
}

// Authenticated must be called only after the API has verified the credential.
// References are fingerprints, not user-selected agent names, tenant names,
// email addresses, or key/token identifiers.
func Authenticated(ctx context.Context, kind, tenant, agent string) {
	info, ok := ctx.Value(contextKey{}).(*requestInfo)
	if !ok {
		return
	}
	switch kind {
	case "agent", "oauth", "account_key", "person":
	default:
		return
	}
	info.mu.Lock()
	defer info.mu.Unlock()
	info.identity = kind
	if tenant != "" {
		info.tenant = fingerprint("tenant:" + tenant)
	}
	if agent != "" {
		info.agent = fingerprint("agent:" + tenant + ":" + agent)
	}
}

func fingerprint(value string) string {
	sum := sha256.Sum256([]byte(value))
	return hex.EncodeToString(sum[:16])
}

// Operation accepts only protocol operation names, never tool names, JSON-RPC
// IDs, parameters or an arbitrary client-supplied method string.
func Operation(ctx context.Context, method string) {
	info, ok := ctx.Value(contextKey{}).(*requestInfo)
	if !ok {
		return
	}
	switch method {
	case "initialize", "server/discover", "ping", "tools/list", "tools/call",
		"notifications/initialized", "notifications/cancelled", "tasks/get", "tasks/result":
	default:
		method = "other"
	}
	info.mu.Lock()
	info.op = method
	info.mu.Unlock()
}

// Handler adds the request ID to existing gateway log events carrying ctx.
// Events outside an HTTP request (startup and sweepers) remain unchanged.
func Handler(next slog.Handler) slog.Handler { return correlatedHandler{next} }

type correlatedHandler struct{ slog.Handler }

func (h correlatedHandler) Handle(ctx context.Context, record slog.Record) error {
	if id := ID(ctx); id != "" {
		record.AddAttrs(slog.String("request_id", id))
	}
	return h.Handler.Handle(ctx, record)
}

func (h correlatedHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	return correlatedHandler{h.Handler.WithAttrs(attrs)}
}

func (h correlatedHandler) WithGroup(name string) slog.Handler {
	return correlatedHandler{h.Handler.WithGroup(name)}
}

// Wrap logs every request, including failures before authentication/parsing.
// The router pattern replaces variable path segments. Unmatched paths are
// omitted; queries, headers, bodies and responses are never inspected.
func Wrap(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		info := &requestInfo{id: hex.EncodeToString(randomID()), identity: "anonymous"}
		r = r.WithContext(context.WithValue(r.Context(), contextKey{}, info))
		w.Header().Set(Header, info.id)
		response := &responseWriter{ResponseWriter: w}
		start := time.Now()
		completed := false
		defer func() {
			status := response.status
			if status == 0 && completed {
				status = http.StatusOK
			}
			// A panic before a response has no returned HTTP status (0).
			// Preserve net/http's panic handling; never log its payload.
			path := "unmatched"
			if r.Pattern != "" {
				path = r.Pattern
				if _, p, ok := strings.Cut(path, " "); ok {
					path = p
				}
			}
			info.mu.Lock()
			identity, tenant, agent, op := info.identity, info.tenant, info.agent, info.op
			info.mu.Unlock()
			attrs := []any{
				"event", "gateway_request", "request_id", info.id,
				"method", httpMethod(r.Method), "path", path, "status", status,
				"duration_ms", float64(time.Since(start)) / float64(time.Millisecond),
				"identity_type", identity, "completed", completed,
			}
			if tenant != "" {
				attrs = append(attrs, "tenant_ref", tenant)
			}
			if agent != "" {
				attrs = append(attrs, "agent_ref", agent)
			}
			if op != "" {
				attrs = append(attrs, "mcp_operation", op)
			}
			// The summary already has the ID; avoid adding it twice through
			// the correlated handler. Existing contextual events use r.Context.
			logger.Info("gateway request", attrs...)
		}()
		next.ServeHTTP(response, r)
		completed = true
	})
}

func randomID() []byte {
	id := make([]byte, 16)
	// crypto/rand.Read fills the buffer or terminates the process on failure.
	_, _ = rand.Read(id)
	return id
}

func httpMethod(method string) string {
	switch method {
	case http.MethodGet, http.MethodHead, http.MethodPost, http.MethodPut,
		http.MethodPatch, http.MethodDelete, http.MethodConnect, http.MethodOptions, http.MethodTrace:
		return method
	}
	return "other"
}

type responseWriter struct {
	http.ResponseWriter
	status int
}

func (w *responseWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

func (w *responseWriter) WriteHeader(status int) {
	if w.status != 0 {
		return
	}
	if status >= 200 {
		w.status = status
	}
	w.ResponseWriter.WriteHeader(status)
}

func (w *responseWriter) Write(p []byte) (int, error) {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	return w.ResponseWriter.Write(p)
}

// FlushError supports streaming through http.ResponseController and records
// the implicit 200 committed by a flush, even if no body was written yet.
func (w *responseWriter) FlushError() error {
	if w.status == 0 {
		w.WriteHeader(http.StatusOK)
	}
	return http.NewResponseController(w.ResponseWriter).Flush()
}
